import json

def exists(path):
    return execute_tool('editor_toolset.toolsets.asset.AssetTools.exists', json.dumps({'path': path}))['returnValue']

def load(path):
    return execute_tool('editor_toolset.toolsets.asset.AssetTools.load_asset', json.dumps({'asset_path': path}))['returnValue']

def get(obj, names):
    return json.loads(execute_tool('editor_toolset.toolsets.object.ObjectTools.get_properties', json.dumps({'instance': obj, 'properties': names}))['returnValue'])

def parent(path):
    return execute_tool('editor_toolset.toolsets.blueprint.BlueprintTools.get_parent', json.dumps({'blueprint': load(path)}))['returnValue']

def dirty(path):
    return execute_tool('editor_toolset.toolsets.asset.AssetTools.is_dirty', json.dumps({'asset_path': path}))['returnValue']

def nodes(bt):
    return execute_tool('aimodule_toolset.toolsets.behavior_tree.BehaviorTreeTools.list_nodes', json.dumps({'behavior_tree': bt}))['returnValue']

def props(obj):
    return json.loads(execute_tool('editor_toolset.toolsets.object.ObjectTools.list_properties', json.dumps({'instance': obj}))['returnValue'])

def skills():
    return execute_tool('ToolsetRegistry.AgentSkillToolset.ListSkills', '{}')['returnValue']

def run():
    required = [
      '/ExtractionOps/AbilitySystem/AbilitySet_ExtractionCore', '/ExtractionOps/Maps/L_ExtractionTest',
      '/ExtractionOps/UI/W_ExtractionInventoryScreen', '/ExtractionOps/UI/W_ExtractionResultScreen',
      '/ExtractionOps/World/Loot/B_ExtractionWorldPickup', '/ExtractionOps/World/Loot/B_ExtractionLootContainer',
      '/ExtractionOps/AI/B_AI_Controller_ExtractionPatrol', '/ExtractionOps/AI/B_AI_Controller_ExtractionFlanker',
      '/ExtractionOps/AI/B_AI_Controller_ExtractionElite', '/ExtractionOps/AI/EQS/EQS_ExtractionFlank',
      '/ExtractionOps/Skills/ExtractionOpsAssetAuthoring', '/ExtractionOps/Skills/ExtractionOpsAuthorityWorkflow',
      '/ExtractionOps/Skills/ExtractionOpsValidationWorkflow'
    ]
    required += ['/ExtractionOps/Items/' + name for name in [
      'DA_Ammo_Rifle','DA_Ammo_Shells','DA_Item_Medkit','DA_Valuable_ScrapMetal','DA_Valuable_PowerCell',
      'DA_Valuable_CircuitBoard','DA_Valuable_OpticModule','DA_Valuable_ServoMotor',
      'DA_Valuable_EncryptedDrive','DA_Valuable_ReactorCore','DA_Valuable_PrototypeChip']]
    missing = [path for path in required if not exists(path)]
    if missing:
        raise RuntimeError('missing assets: ' + str(missing))
    ability_parent = '/Script/ExtractionOpsRuntime.ExtractionGameplayAbility_RangedWeapon'
    fire_parents = {path: parent(path) for path in [
      '/ExtractionOps/Weapons/Rifle/GA_Weapon_Fire_ExtractionRifle',
      '/ExtractionOps/Weapons/Shotgun/GA_Weapon_Fire_ExtractionShotgun']}
    if any(value.get('refPath') != ability_parent for value in fire_parents.values()):
        raise RuntimeError('fire ability parent mismatch: ' + str(fire_parents))
    component_action = {'refPath': '/ExtractionOps/ExtractionOps.ExtractionOps:GameFeatureAction_AddComponents_0'}
    components = get(component_action, ['componentList'])['componentList']
    component_text = str(components)
    for expected in ['ExtractionMatchStateComponent','ExtractionRunStateComponent','ExtractionInventoryComponent','ExtractionRaidLifecycleComponent','ExtractionThreatDirectorComponent']:
        if expected not in component_text:
            raise RuntimeError('missing game feature component ' + expected)
    flank_queries = []
    bt = load('/ExtractionOps/AI/BT/BT_ExtractionFlanker')
    for node in nodes(bt):
        if 'eQSRequest' in props(node):
            request = get(node, ['eQSRequest']).get('eQSRequest')
            if request and 'EQS_ExtractionFlank' in str(request.get('queryTemplate')):
                flank_queries.append(str(node))
    if len(flank_queries) != 1:
        raise RuntimeError('flank EQS wiring mismatch: ' + str(flank_queries))
    registered = skills()
    project_skills = [key for key in registered.keys() if key.startswith('/ExtractionOps/Skills/') ]
    if len(project_skills) != 3:
        raise RuntimeError('project skill count mismatch: ' + str(project_skills))
    dirty_assets = [path for path in required if dirty(path)]
    if dirty_assets:
        raise RuntimeError('dirty assets remain: ' + str(dirty_assets))
    return {'requiredAssetCount': len(required), 'fireParents': fire_parents, 'gameFeatureComponentCount': len(components), 'flankQueryCount': len(flank_queries), 'skills': project_skills, 'dirtyAssets': []}
